import{_ as t,o as l,c as s,a5 as e,j as a}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"LLMのパイプライン並列：層を分けると、なぜGPUに待ち時間が生まれるのか","description":"","frontmatter":{"title":"LLMのパイプライン並列：層を分けると、なぜGPUに待ち時間が生まれるのか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"2段に4つのマイクロバッチを流し、前向き計算で生まれる充填・定常・排出とバブルを図で追う。逆伝播、段間の通信と負荷不均衡を区別する。","aliases":["パイプライン並列","パイプラインモデル並列","Pipeline Parallelism","GPipe","マイクロバッチ","パイプラインバブル"],"verification":"GPipe原論文と分散Megatron-LM論文に照合し、WindowsのPython 3.12.4で2段×4マイクロバッチの時系列と空き枠を検算（2026-11-21）"}},"headers":[],"relativePath":"algorithms/pipeline-parallelism.md","filePath":"algorithms/pipeline-parallelism.md"}'),i={name:"algorithms/pipeline-parallelism.md"};function n(o,r,d,p,h,g){return l(),s("div",null,[...r[0]||(r[0]=[e('<h1 id="llmのパイプライン並列-層を分けると、なぜgpuに待ち時間が生まれるのか" tabindex="-1">LLMのパイプライン並列：層を分けると、なぜGPUに待ち時間が生まれるのか <a class="header-anchor" href="#llmのパイプライン並列-層を分けると、なぜgpuに待ち時間が生まれるのか" aria-label="Permalink to &quot;LLMのパイプライン並列：層を分けると、なぜGPUに待ち時間が生まれるのか&quot;">​</a></h1><p>LLMの前半の層をGPU 0、後半の層をGPU 1に置きます。GPU 1は、最初の入力について前半の計算結果が届くまで待ちます。一方、それを受け取ったあとは、GPU 0が次の入力の前半を計算できます。<strong>パイプライン並列</strong>は、連続する層をいくつかの段に分け、別々の入力の計算を時間的に重ねる方法です。<a href="https://arxiv.org/pdf/1811.06965#page=3" target="_blank" rel="noreferrer">GPipe原論文 §2・図2</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>2段に4つのマイクロバッチを流す例から、GPUが両方動く区間と、片方が待つ区間を数えられます。層の分割、段間の通信、学習の逆伝播が、それぞれどこで起きるかを説明できます。</p><h2 id="前半と後半の層に、同じ入力を順に通す" tabindex="-1">前半と後半の層に、同じ入力を順に通す <a class="header-anchor" href="#前半と後半の層に、同じ入力を順に通す" aria-label="Permalink to &quot;前半と後半の層に、同じ入力を順に通す&quot;">​</a></h2><p>GPU 0とGPU 1に、連続する層のまとまりを1つずつ割り当てます。それぞれを前段・後段と呼びます。1つの入力を進めるには、前段の出力を後段の入力にする必要があります。前段だけを通った入力の<strong>活性値</strong>（層の計算から得られた中間の数値）をGPU間で受け渡します。<a href="https://arxiv.org/pdf/1811.06965#page=3" target="_blank" rel="noreferrer">GPipe原論文 §2.1–2.2</a></p><p>GPipeでは、ひとまとまりの学習入力（ミニバッチ）をさらに小分けにし、<strong>マイクロバッチ</strong>として順に流します。ここではその小分けをMB1〜MB4と呼びます。後段がMB1を計算している間、空いた前段はMB2を進められます。この例で分けているのは処理する入力のまとまりです。各マイクロバッチは前段・後段の両方を通ります。<a href="https://arxiv.org/pdf/1811.06965#page=3" target="_blank" rel="noreferrer">GPipe原論文 §2.2・図2c</a></p><h2 id="_2段×4マイクロバッチを前向きに流す" tabindex="-1">2段×4マイクロバッチを前向きに流す <a class="header-anchor" href="#_2段×4マイクロバッチを前向きに流す" aria-label="Permalink to &quot;2段×4マイクロバッチを前向きに流す&quot;">​</a></h2><p>すべてのマイクロバッチを最初から投入でき、各段の計算が同じ長さの1スロットで終わるとします。段間通信と起動の時間は省きます。図は<strong>順伝播</strong>（入力から出力へ進む計算）だけを数える概念例です。</p>',9),a("figure",{style:{margin:"1rem 0"}},[a("div",{role:"img","aria-label":"2台のGPUで前向き計算を5スロット実行。第1スロットは充填でGPU0がMB1、GPU1は待ち。第2〜4スロットは定常でGPU0がMB2、MB3、MB4、GPU1がMB1、MB2、MB3を並行処理。第5スロットは排出でGPU0は待ち、GPU1がMB4を処理する。",style:{"max-width":"36rem","font-size":"0.9em","font-variant-numeric":"tabular-nums"}},[a("div",{style:{display:"grid","grid-template-columns":"4.8em repeat(5, minmax(0, 1fr))",gap:"0.32rem 0.2rem","align-items":"center","text-align":"center"}},[a("span"),a("strong",{"data-phase":"fill"},"充填"),a("strong",{"data-phase":"steady",style:{"grid-column":"span 3"}},"定常"),a("strong",{"data-phase":"drain"},"排出"),a("span",{style:{"text-align":"left"}},"スロット"),a("span",null,"1"),a("span",null,"2"),a("span",null,"3"),a("span",null,"4"),a("span",null,"5"),a("div",{"data-pp-stage":"front",style:{display:"contents"}},[a("strong",{style:{"text-align":"left"}},"前段 GPU 0"),a("span",{"data-slot":"1","data-mb":"1",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB1"),a("span",{"data-slot":"2","data-mb":"2",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB2"),a("span",{"data-slot":"3","data-mb":"3",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB3"),a("span",{"data-slot":"4","data-mb":"4",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB4"),a("span",{"data-slot":"5","data-mb":"",style:{background:"var(--vp-c-warning-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"待ち")]),a("div",{"data-pp-stage":"back",style:{display:"contents"}},[a("strong",{style:{"text-align":"left"}},"後段 GPU 1"),a("span",{"data-slot":"1","data-mb":"",style:{background:"var(--vp-c-warning-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"待ち"),a("span",{"data-slot":"2","data-mb":"1",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB1"),a("span",{"data-slot":"3","data-mb":"2",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB2"),a("span",{"data-slot":"4","data-mb":"3",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB3"),a("span",{"data-slot":"5","data-mb":"4",style:{background:"var(--vp-c-brand-soft)","border-radius":"4px",padding:"0.3rem 0.1rem"}},"MB4")])])]),a("figcaption",{style:{"font-size":"0.875rem","margin-top":"0.55rem"}},"同じ番号のMBが前段から後段へ移る。色を分けた「待ち」は、片方のGPUにその区間で実行する前向き計算がないことを示す。")],-1),e('<ul><li><strong>充填（1）</strong>では、後段に前段の出力がまだ届いていません。</li><li><strong>定常（2〜4）</strong>では、前段と後段が別のマイクロバッチを同時に計算します。</li><li><strong>排出（5）</strong>では、前段は4件を渡し終え、後段だけが最後の出力を求めます。</li></ul><p>この例では5スロットで4つの出力がそろいます。2台×5スロットのうち2枠が空いているため、空きの割合は <strong>2/10 = 20%</strong> です。前段と後段の依存関係から生まれる空きが<strong>パイプラインのバブル</strong>です。重ねずに1件ずつ前段・後段を実行すると全体は8スロットですが、最初のMB1の所要は両方とも2スロットです。重ねて改善したのは、後続を含めた全体の処理量です。<a href="https://arxiv.org/pdf/1811.06965#page=3" target="_blank" rel="noreferrer">GPipe原論文 §2.2–2.3・図2</a></p><h2 id="学習では後段から前段へ勾配を戻す" tabindex="-1">学習では後段から前段へ勾配を戻す <a class="header-anchor" href="#学習では後段から前段へ勾配を戻す" aria-label="Permalink to &quot;学習では後段から前段へ勾配を戻す&quot;">​</a></h2><p>図の範囲には、学習に必要な<strong>逆伝播</strong>（出力側から各重みの勾配を求める計算）は入っていません。GPipeのスケジュールでは、ミニバッチの前向き処理の後に逆伝播を行います。段間では、順伝播で境界の活性値を前段から後段へ送り、逆伝播でその活性値に関する勾配を後段から前段へ返します。各マイクロバッチの勾配を同じ重みで求め、すべてを蓄積してからミニバッチの終わりに更新します。<a href="https://arxiv.org/pdf/1811.06965#page=3" target="_blank" rel="noreferrer">GPipe原論文 §2.2・図2c</a> · <a href="https://arxiv.org/html/2104.04473v5#S2.SS2.SSS1" target="_blank" rel="noreferrer">分散Megatron-LM論文 §2.2.1・図3</a></p><h2 id="通信と段ごとの処理時間でも、空き方は変わる" tabindex="-1">通信と段ごとの処理時間でも、空き方は変わる <a class="header-anchor" href="#通信と段ごとの処理時間でも、空き方は変わる" aria-label="Permalink to &quot;通信と段ごとの処理時間でも、空き方は変わる&quot;">​</a></h2><p>実際の段間通信では、マイクロバッチごとの中間ベクトルを渡します。転送を別の計算に重ねられる場合もありますが、受信が間に合わなければ後段はその入力を開始できません。転送時間には中間値の大きさ、GPU間の帯域、送受信の開始や待ちにかかる時間が関わります。マイクロバッチを細かくすると、境界を通る受け渡しの回数も増えます。<a href="https://arxiv.org/pdf/1811.06965#page=4" target="_blank" rel="noreferrer">GPipe原論文 §2.2–2.3</a> · <a href="https://arxiv.org/html/2104.04473v5#S3" target="_blank" rel="noreferrer">分散Megatron-LM論文 §3.2・§3.4</a></p><p>前段の計算が遅ければ、後段は入力が届くのを待ちます。後段が遅ければ、前段から渡された結果がたまり、待ち行列の空きがなくなれば前段も止まります。このため、層の数を半分ずつにするだけでは負荷がそろわない場合があります。GPipeは各段の推定コストを均す分割を使います。図の20%は、同じ長さの段で通信を省いた場合の値です。<a href="https://arxiv.org/pdf/1811.06965#page=4" target="_blank" rel="noreferrer">GPipe原論文 §2.2–2.3</a></p><h2 id="同じ「gpuに分ける」でも、分ける対象が違う" tabindex="-1">同じ「GPUに分ける」でも、分ける対象が違う <a class="header-anchor" href="#同じ「gpuに分ける」でも、分ける対象が違う" aria-label="Permalink to &quot;同じ「GPUに分ける」でも、分ける対象が違う&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>分ける対象</th><th>GPU間で渡すものの例</th></tr></thead><tbody><tr><td>パイプライン並列</td><td>連続する層のまとまり</td><td>次の段に渡す活性値</td></tr><tr><td>テンソル並列</td><td>同じ層の計算や重み</td><td>同じ出力への部分和</td></tr><tr><td>エキスパート並列</td><td>専門家の配置と各トークンの行き先</td><td>専門家への入力と計算結果</td></tr></tbody></table><p>パイプライン並列では、同じマイクロバッチが決まった順番で段を通ります。<a href="/study/algorithms/tensor-parallelism.html">テンソル並列</a>では、同じ層の部分和を複数GPUで計算し、足し合わせる構成があります。<a href="/study/algorithms/expert-parallelism.html">エキスパート並列</a>では、トークンごとに選んだ専門家へベクトルを送ります。1つの段の内部でテンソル並列などを使う構成もあります。<a href="https://arxiv.org/html/2104.04473v5#S2" target="_blank" rel="noreferrer">分散Megatron-LM論文 §2</a> · <a href="https://arxiv.org/html/2006.16668#S3" target="_blank" rel="noreferrer">GShard原論文 §3</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>パイプライン並列は連続する層を段に分け、複数のマイクロバッチの計算を重ねます。</li><li>2段×4マイクロバッチで各段が同じ時間、通信を省く場合、5スロットのうち各GPUに1枠ずつ空きが生まれます。</li><li>学習では逆伝播も必要です。GPipeはマイクロバッチごとの勾配をため、ミニバッチの終わりに更新します。</li><li>実際には段間通信と負荷の偏りも待ち時間を作ります。テンソル並列やエキスパート並列とは分ける対象が違います。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>MB1に対して、後段はなぜスロット1で計算できない？</summary><p>後段はMB1を前段で計算した結果を必要とするので、スロット1の終了を待ちます。</p></details><details class="details custom-block"><summary>5スロットの図から、学習の1ステップの所要時間も分かる？</summary><p>図は前向きだけを扱います。学習では逆伝播と重みの更新があり、実機では段間通信などの時間も加わります。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日にGPipeの原論文と分散Megatron-LMの論文を確認し、WindowsのPython 3.12.4で、依存関係に従った前向きの時系列、5スロット、空き2枠を検算しました。GPU間通信の実行、学習時間、実モデルの性能は測定していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/algorithms/tensor-parallelism.html">LLMのテンソル並列</a> — 同じ層をGPU間で分担して部分和を足す方法を読む。</li><li><a href="/study/algorithms/expert-parallelism.html">MoEのエキスパート並列</a> — トークンを専門家のいるGPUへ配送し、結果を戻す方法を追う。</li><li><a href="/study/algorithms/disaggregated-prefill-decode.html">Prefillとdecodeの分離</a> — 推論を処理段階で分け、GPU群の間でKVを渡す例を読む。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/1811.06965" target="_blank" rel="noreferrer">Yanping Huangほか — GPipe（NeurIPS 2019）</a> — 層の分割、マイクロバッチ、同期した勾配更新、バブル。</li><li><a href="https://arxiv.org/html/2104.04473v5#S2" target="_blank" rel="noreferrer">Deepak Narayananほか — Efficient Large-Scale Language Model Training on GPU Clusters Using Megatron-LM（2021）</a> — パイプラインとテンソルの組み合わせ、段間通信、学習スケジュール。</li></ul>',21)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
